<template>
    <div>
        <loader :is-visible="isLoading"></loader>

        <div class="theme-primary partition" id="NewRequisitionid">
            <span class="p-name text-white">
                {{ $t("AddPurchaseRequest") }}
            </span>
            <span class="p-actions float-right">
                <router-link to="/AssetRequisition/NewAssetRequisitionListing" class="p-action-btn text-white"
                    data-toggle="tooltip" title="Back to list">
                    <i class="fa fa-angle-double-left pr-2"></i><br>
                    <span>{{ $t("BacktoList") }}</span>
                </router-link>
            </span>
        </div>
        <div class="right-content right-content-expand border p-3">
            <dynamic-form lang="en" ref="FieldUpdate" :mandatorytext='MandatoryString' :buttons="false"
                :schema="FormSchema">
                <template v-slot:tgslot-Location="{ data }">
                    <Field name="Location" class="w-100" :rules="requiredRule" v-slot="{ errors }">

                        <tree-view v-model="data.fieldInfo.value" :options="options" placeholder="Select Location"
                            v-on:input="onChangeLocation(data.fieldInfo.value)" :show-count="true"
                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }">
                        </tree-view>
                        <span v-if="errors[0]" name="Location" class="invalid-feedback d-block">{{ errors[0]
                            }}</span>

                    </Field>
                </template>
            </dynamic-form>
            <div class="col-lg-12 mb-3 p-0">
                <div class="row flex-row-reverse">
                    <div class="col-lg-6 text-right">
                        <a href="javascript:;" @click="saveNewRequisition(values, errors, 'ACT')"
                            class="btn btn-success  pr-2 mr-2"><i class="fa fa-save pr-2"></i>{{ updateRequistionId ==
                                0 ? $t("Save") : $t("Update") }}</a>
                        <a v-if="productItem.AssetRequisitionId == undefined || productItem.RequisitionId == undefined && productItem.StatusName == 'DRAFT'"
                            href="#" @click.prevent="saveNewRequisitionAsDraft('Draft')"
                            class="btn btn-warning pr-2 mr-2">
                            <i class="fa fa-save pr-2"></i> {{ $t('SaveAsDraft') }}
                        </a>
                        <router-link to="/AssetRequisition/NewAssetRequisitionListing" class="btn btn-danger "
                            data-original-title="Cancel">
                            <i class="fa fa-close pr-2"></i>{{ $t("Cancel") }}
                        </router-link>
                    </div>
                    <!-- <div class="col-lg-6 py-2">
                        <span class="mandatory">{{ $t("MandatoryString") }}</span>
                    </div> -->
                </div>
            </div>
        </div>

    </div>
</template>
<script>

import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
import DataService from '../../service/DataService';

export default {
    components: {
        'tree-view': Treeselect
    },
    data() {
        return {
            requiredRule: { 'required': true },
            MandatoryString: this.$t('MandatoryString'),
            isLoading: false,
            options: [],
            AssetType: [],
            updateRequistionId: 0,
            Reason: "",
            title: "",
            productItem: {
                StatusName: ''
            },
            ProductData: [],
            FormSchema: [
                {

                    layoutType: "double",
                    Data: [
                        {
                            astype: "SlotField",
                            label: this.$t('Location'),
                            name: "Location",
                            value: null,
                            placeholder: "Select Location",
                            disabled: true,
                            config: {
                                options: [],
                            },
                            validationRules: {
                                "required": true
                            },
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('ProductType'),
                            name: "product_type",
                            value: "",
                            placeholder: "",
                            disabled: false,
                            validationRules: { "required": true, max: 100 },
                            config: {
                                options: [
                                ],
                                onChange: this.getProductNameByProductType

                            },

                        },

                        {
                            astype: "RadioField",
                            label: this.$t('IsExistingProduct'),
                            name: "existing_product",
                            value: "0",
                            placeholder: "",
                            disabled: false,
                            config: {
                                options: [{
                                    value: "1",
                                    name: this.$t('Yes')
                                }, {
                                    value: "0",
                                    name: this.$t('No')
                                }],
                                onChange: this.onChangeExistingProduct
                            },
                            validationRules: {
                                "required": true
                            }
                        },

                        {
                            astype: "TextField",
                            label: this.$t("ProductName"),
                            name: "product_name",
                            value: '',
                            placeholder: "",
                            visibility: true,
                            validationRules: { "required": true },
                        },
                        {
                            astype: "SelectField",
                            label: this.$t("Product"),
                            name: "product",
                            value: '',
                            placeholder: "",
                            visibility: false,
                            validationRules: { "required": true },
                            config: {
                                options: [],
                            },
                        },
                        {
                            astype: "NumericField",
                            label: this.$t("RequestedQuantity"),
                            name: "requested_quantity",
                            value: '',
                            placeholder: "",
                            disabled: false,
                            validationRules: { "required": true },
                            config: {
                                onKeyUp: this.setRequestedValue
                            },
                        },
                        {
                            astype: "NumericField",
                            label: this.$t("ExpectedQuantity"),
                            name: "expected_quantity",
                            value: '',
                            placeholder: "",
                            disabled: false,
                            validationRules: { "required": false },
                            config: {
                                onKeyUp: this.setExpectedValue
                            },
                        },

                    ]
                },
                {
                    layoutType: "double",
                    Data: [

                        {
                            astype: "TextAreaField",
                            label: this.$t('Specification'),
                            name: "specification",
                            value: "",
                            placeholder: "",
                            config: {
                                rows: 5
                            },
                            validationRules: { "required": true, max: 250 },

                        },

                        {
                            astype: "TextAreaField",
                            label: this.$t('Reason'),
                            name: "reason",
                            value: "",
                            placeholder: "",
                            config: {
                                rows: 5
                            },
                            validationRules: { "required": true, max: 250 },

                        },

                    ]
                },

                // {
                //     layoutType: "double",
                //     Data: [
                //         {
                //             astype: "TextField",
                //             label: this.$t("Title"),
                //             name: "title",
                //             value: '',
                //             placeholder: "",
                //             validationRules: { "required": true },

                //         },
                //         {
                //             astype: "TextAreaField",
                //             label: this.$t('Reason'),
                //             name: "reason",
                //             value: "",
                //             placeholder: "",
                //             config: {
                //                 rows: 5
                //             },
                //             validationRules: { "required": true, max: 250 },

                //         },
                //     ]
                // },

            ],
            buttons: [{
                type: "submit",
                class: "btn btn-info",
                text: "<i class='fa fa-plus pr-2'></i>Add To List",
                isVisible: true
            }],

        }

    },
    async created() {
        var vm = this;
        await vm.GetLocationByCompanyId();
        await vm.GetAssetType();
        if (this.$route.params.reqForm == 'ProductTypeList') {
            this.productItem = this.$route.params.items;
            if (this.productItem != null && this.productItem != '' && this.productItem != 'undefined') {
                vm.updateRequistionId = this.productItem.AssetRequisitionId;
                vm.$refs.FieldUpdate.updateProperty("Location", "value", this.productItem.LocationId);
                vm.$refs.FieldUpdate.updateProperty("product_type", "value", this.productItem.AssetTypeId);
                vm.$refs.FieldUpdate.updateProperty("requested_quantity", "value", this.productItem.Quantity.toLocaleString('en-US'));
                vm.$refs.FieldUpdate.updateProperty("specification", "value", this.productItem.Specification);
                vm.$refs.FieldUpdate.updateProperty("reason", "value", this.productItem.Description);
                vm.$refs.FieldUpdate.updateProperty("existing_product", "value", this.productItem.IsExistProduct);
                vm.$refs.FieldUpdate.updateProperty("expected_quantity", "value", this.productItem.ExpectedQuantity.toLocaleString('en-US'));
                const isExistProduct = this.productItem.IsExistProduct;
                if (isExistProduct == true) {
                    await vm.getProductNameByProductType('', { value: this.productItem.AssetTypeId });
                    await vm.onChangeExistingProduct('', { value: '1' });
                    vm.$refs.FieldUpdate.updateProperty("product", "value", this.productItem.AssetCatalougeId);
                } else {
                    vm.$refs.FieldUpdate.updateProperty("product_name", "value", this.productItem.ProductName);
                }

            }
        }
        if (this.$route.params.reqForm == 'ProductEdit') {
            this.productItem = this.$route.params.items;
            if (this.productItem != null && this.productItem != '' && this.productItem != 'undefined') {
                vm.updateRequistionId = this.productItem.RequisitionId;
                if (this.productItem && this.productItem.RequisitionId) {
                    this.productItem.AssetRequisitionId = vm.updateRequistionId
                }
                vm.$refs.FieldUpdate.updateProperty("Location", "value", this.productItem.location_id);
                vm.$refs.FieldUpdate.updateProperty("product_type", "value", this.productItem.AssetTypeId);
                vm.$refs.FieldUpdate.updateProperty("requested_quantity", "value", this.productItem.Quantity.toLocaleString('en-US'));
                vm.$refs.FieldUpdate.updateProperty("specification", "value", this.productItem.Specification);
                vm.$refs.FieldUpdate.updateProperty("reason", "value", this.productItem.description);
                vm.$refs.FieldUpdate.updateProperty("existing_product", "value", this.productItem.IsExistProduct);
                vm.$refs.FieldUpdate.updateProperty("expected_quantity", "value", this.productItem.ExpectedQuantity.toLocaleString('en-US'));
                const isExistProduct = this.productItem.IsExistProduct;
                if (isExistProduct == true) {
                    await vm.getProductNameByProductType('', { value: this.productItem.AssetTypeId });
                    await vm.onChangeExistingProduct('', { value: '1' });
                    vm.$refs.FieldUpdate.updateProperty("product", "value", this.productItem.AssetCatalougeId);
                } else {
                    vm.$refs.FieldUpdate.updateProperty("product_name", "value", this.productItem.productName);
                }

            }
        }
    },
    methods: {
        getLocationById(locationId) {
            const find = (data, targetId) => {
                for (const item of data) {
                    if (String(item.id) === String(targetId)) {
                        return item;
                    }
                    if (item.children && item.children.length > 0) {
                        const found = find(item.children, targetId);
                        if (found) return found;
                    }
                }
                return null;
            };

            return find(this.options, locationId);
        },


        onChangeLocation(value) {
            if (this.updateRequistionId != 0) {
                return;
            }
            let productTypeId = this.$refs.FieldUpdate.getPropertyValue("product_type", "value");
            if (productTypeId != '' && productTypeId != undefined) {
                this.$refs.FieldUpdate.updateProperty("product_type", "value", '');
                this.$refs.FieldUpdate.updateProperty("product_name", "value", '');
                this.$refs.FieldUpdate.updateProperty("product", "value", '');
                this.$refs.FieldUpdate.updateProperty("product", "config.options", []);
            }
            else {
                //
            }

        },
        onChangeExistingProduct(event, data) {
            if (data.value == '1') {
                this.$refs.FieldUpdate.updateProperty("product_name", "visibility", false);
                this.$refs.FieldUpdate.updateProperty("product", "visibility", true);
            } else {
                this.$refs.FieldUpdate.updateProperty("product_name", "visibility", true);
                this.$refs.FieldUpdate.updateProperty("product", "visibility", false);
            }
        },
        async getProductNameByProductType(event, data) {
            try {
                this.isLoading = true;
                const locationId = this.$refs.FieldUpdate.getPropertyValue("Location", "value");
                const url = `id=${data.value}&issueTo=0&locationId=${locationId}&requestFrom=`;
                const response = await DataService.GetCompanyAssestCatalogs(url);
                if (response.data != null) {
                    const responseData = response.data;
                    this.ProductData = [];
                    responseData.forEach(ele => {
                        this.ProductData.push({
                            name: ele.NAME,
                            value: ele.ASSET_CATALOGUE_ID
                        });
                    });
                    this.$refs.FieldUpdate.updateProperty("product", "config.options", this.ProductData);
                    this.$refs.FieldUpdate.UpdateKeyValue();
                }
            } catch (error) {
                console.error("Error fetching product data:", error);
            } finally {
                this.isLoading = false;
            }
        },

        async GetLocationByCompanyId() {
            var vm = this;
            var url = `reqForm=assetassignment`
            await DataService.GetLocationByuserId(url).then(response => {
                vm.FindalLocationArray = [];
                response.data.data.forEach((value) => {
                    var CheckIfExist = vm.FindalLocationArray.filter(function (el) {
                        return el.COMPANY_LOCATION_ID == value.COMPANY_LOCATION_ID;
                    });
                    if (CheckIfExist.length == 0) {
                        if (value.PARENT_LOCATION_ID == null) {
                            let locationId = value.COMPANY_LOCATION_ID
                            let rslt = vm.getChildLocation(locationId, value, response.data.data)
                            vm.FindalLocationArray.push(rslt)
                        }
                    }
                });
                vm.options = vm.FindalLocationArray;
            });
        },
        getChildLocation(locationId, currentItem, data) {
            let ths = this;
            let treeArray = {};
            treeArray = {
                id: currentItem.COMPANY_LOCATION_ID,
                label: currentItem.LOCATION_NAME
            }
            let retrunArray = treeArray;
            var childArray = data.filter(function (el) {
                return el.PARENT_LOCATION_ID == locationId;
            });
            let finalChildArray = [];
            childArray.forEach((value) => {
                let ChildfolderId = value.COMPANY_LOCATION_ID
                var CheckIfExist1 = finalChildArray.filter(function (el) {
                    return el.COMPANY_LOCATION_ID == value.COMPANY_LOCATION_ID;
                });
                if (CheckIfExist1.length == 0) {
                    var CheckIfExist = data.filter(function (el) {
                        return el.PARENT_LOCATION_ID == ChildfolderId;
                    });
                    if (CheckIfExist != null && CheckIfExist.length > 0) {
                        let rslt = ths.getChildLocation(ChildfolderId, value, data);
                        finalChildArray.push(rslt);
                    } else {
                        treeArray = {
                            id: `${value.COMPANY_LOCATION_ID}`,
                            label: `${value.LOCATION_NAME}`
                        }
                        finalChildArray.push(treeArray);
                    }
                }
            });
            retrunArray.children = finalChildArray;
            return retrunArray;
        },
        async GetAssetType() {
            var vm = this;
            vm.isLoading = true;
            var url = `type=ITEMCODE&issueTo=&locationId=`;
            await DataService.GetAssetTypeCustom(url).then(response => {
                let responseData = JSON.parse(response.data);
                let obj = {};
                responseData.forEach(ele => {
                    obj = {
                        name: ele.ASSETTYPE,
                        value: ele.ASSETID
                    }
                    vm.AssetType.push(obj);
                })
                vm.$refs.FieldUpdate.updateProperty("product_type", "config.options", vm.AssetType);
                vm.$refs.FieldUpdate.UpdateKeyValue();
                vm.isLoading = false;
            })

        },
        parseFormattedNumber(value) {
            if (typeof value === 'string') {
                const numericString = value.replace(/,/g, '').trim(); // Remove commas & whitespace
                const number = parseInt(numericString, 10);
                return isNaN(number) ? 0 : number; // Handle invalid input
            }

            return typeof value === 'number' ? value : 0;
        },
        saveNewRequisition(values, errors, ACT) {
            let status = ACT;
            var vm = this;
            vm.$refs.FieldUpdate.validateForm.validate().then(result => {
                if (result) {
                    let name = ''
                    let productTypeName = '';
                    let locationId = this.$refs.FieldUpdate.getPropertyValue("Location", "value");
                    // let hostingUrl = process.env.VUE_APP_CURRENT_SITE_ROOT_URL;
                    // let navigateUrl = hostingUrl + '/AssetRequisition/NewAssetRequisitionListing';
                    const result = this.getLocationById(locationId);
                    let productType = this.$refs.FieldUpdate.getPropertyValue("product_type", "value");
                    let matchedObject =  this.AssetType.find(x => x.value == productType);
                    productTypeName = matchedObject ? matchedObject.name : '';
                    let product = this.$refs.FieldUpdate.getPropertyValue("product", "value");
                    let productName = this.$refs.FieldUpdate.getPropertyValue("product_name", "value");
                    let IsExistingProduct = this.$refs.FieldUpdate.getPropertyValue("existing_product", "value");
                    if (IsExistingProduct === '1') {
                        const obj = this.ProductData.find(x => x.value == product);
                        name = obj ? obj.name : '';
                    } else {
                        name = productName;
                    }

                    let requestedQuantity = this.parseFormattedNumber(this.$refs.FieldUpdate.getPropertyValue("requested_quantity", "value"));
                    let specification = this.$refs.FieldUpdate.getPropertyValue("specification", "value");
                    let reason = this.$refs.FieldUpdate.getPropertyValue("reason", "value");
                    let exceptedQuantity = this.parseFormattedNumber(this.$refs.FieldUpdate.getPropertyValue("expected_quantity", "value"));
                    let obj = {
                        RequisitionId: (vm.updateRequistionId ? vm.updateRequistionId : 0),
                        location: locationId,
                        productname: name,
                        productId: product,
                        productType: productType,
                        isExistingProduct: IsExistingProduct,
                        quantity: requestedQuantity,
                        description: reason,
                        specification: specification,
                        status: status,
                        exceptedQuantity: exceptedQuantity,
                        quotes: [],
                        purchases: [],
                        notificationTable: [
                            {
                                "Location": result.label,
                                "ProductType": productTypeName,
                                "IsExistingProduct": IsExistingProduct,
                                "ProductName": name,
                                "RequestedQuantity": requestedQuantity,
                                "EstimatedTotalCost": exceptedQuantity,
                                "Specification": specification,
                                "Reason": reason,
                                // "Url":  navigateUrl
                            }
                        ]
                    }
                    var formData = new FormData();
                    formData.append("postString", JSON.stringify(obj));
                    vm.isLoading = true;
                    DataService.AddUpdateNewRequisition(formData).then(response => {
                        if (response.data.msg == 'add') {
                            vm.isLoading = false;
                            vm.ShowAlert(vm.$t("NewProducttypeRequestSuccessfullyAdded"), "Success", vm.$t('Alert'));
                            return vm.$router.push({ path: '/AssetRequisition/NewAssetRequisitionListing' });
                        }
                        else if (response.data.msg == 'update') {
                            vm.isLoading = false;
                            vm.ShowAlert(vm.$t("NewProducttypeRequestSuccessfullyUpdated"), "Success", vm.$t('Alert'));
                            return vm.$router.push({ path: '/AssetRequisition/NewAssetRequisitionListing' });
                        }
                        else {
                            vm.isLoading = false;
                            return vm.ShowAlert(vm.$t("NewProductTypeRequestFailed"), "failure", vm.$t('Alert'));
                        }
                    })
                }
                else {
                    vm.ShowAlert(vm.$t("CorrectHighlightedErrors"), "failure", vm.$t('Alert'));
                }
            });

        },

        saveNewRequisitionAsDraft(event) {
            let status = event;
            var vm = this;
            vm.$refs.FieldUpdate.validateForm.validate().then(result => {
                if (result) {
                    let locationId = this.$refs.FieldUpdate.getPropertyValue("Location", "value");
                    let productType = this.$refs.FieldUpdate.getPropertyValue("product_type", "value");
                    let IsExistingProduct = this.$refs.FieldUpdate.getPropertyValue("existing_product", "value");
                    let product = this.$refs.FieldUpdate.getPropertyValue("product", "value");
                    let productName = this.$refs.FieldUpdate.getPropertyValue("product_name", "value");
                    let requestedQuantity = this.parseFormattedNumber(this.$refs.FieldUpdate.getPropertyValue("requested_quantity", "value"));
                    let specification = this.$refs.FieldUpdate.getPropertyValue("specification", "value");
                    let reason = this.$refs.FieldUpdate.getPropertyValue("reason", "value");
                    let exceptedQuantity = this.parseFormattedNumber(this.$refs.FieldUpdate.getPropertyValue("expected_quantity", "value"));

                    let obj = {
                        RequisitionId: (vm.updateRequistionId ? vm.updateRequistionId : 0),
                        location: locationId,
                        productname: productName,
                        productId: product,
                        productType: productType,
                        isExistingProduct: IsExistingProduct,
                        quantity: requestedQuantity,
                        description: reason,
                        specification: specification,
                        status: status,
                        exceptedQuantity: exceptedQuantity,
                        quotes: [],
                        purchases: [],
                        notificationTable: [{
                            productname: productName,
                            description: reason,
                            quantity: requestedQuantity
                        }]
                    }
                    var formData = new FormData();
                    formData.append("postString", JSON.stringify(obj));
                    vm.isLoading = true
                    DataService.AddUpdateNewRequisition(formData).then(response => {

                        if (response.data.msg == 'add') {
                            vm.isLoading = false;

                            vm.ShowAlert(vm.$t("NewProducttypeRequestdraft"), "Success", vm.$t('Alert'));
                            return vm.$router.push({ path: '/AssetRequisition/NewAssetRequisitionListing' });
                        }
                        else if (response.data.msg == 'update') {
                            vm.isLoading = false;

                            vm.ShowAlert(vm.$t("NewProducttypeRequestupdateddraft"), "Success", vm.$t('Alert'));
                            return vm.$router.push({ path: '/AssetRequisition/NewAssetRequisitionListing' });
                        }
                        else {

                            vm.isLoading = false;
                            return vm.ShowAlert(vm.$t("NewProducttypeRequestfailed"), "failure", vm.$t('Alert'));
                        }
                    })

                }
            })

        },
        setRequestedValue(event, data) {
            var vm = this;
            if (data.value == "") {
                return;
            }
            if (data.value == "0") {
                vm.ShowAlert(vm.$t("Quantity must be equal to or greater than 1"), "danger", vm.$t('Alert'));
                this.$refs.FieldUpdate.updateProperty("requested_quantity", "value", "");
            }
            const disallowedKeys = ['+', '-', '=', 'e', '.'];
            if (disallowedKeys.includes(event.key)) {
                event.preventDefault();
                let requestedQuantity = data.value;
                requestedQuantity = requestedQuantity.replace(/\./g, '');
                return this.$refs.FieldUpdate.updateProperty("requested_quantity", "value", requestedQuantity);

            }
            let value = data.value.replace(/\D/g, ''); // Remove non-numeric characters
            if (value.length > 5) {
                value = value.slice(0, 5); // Trim to 10 digits max
            }
            let formattedValue = Number(value).toLocaleString('en-US');
            this.$refs.FieldUpdate.updateProperty("requested_quantity", "value", formattedValue);
        },
        setExpectedValue(event, data) {

            if (data.value == "") {
                return;
            }
            const disallowedKeys = ['+', '-', '=', 'e', '.'];
            // Prevent input of disallowed characters
            if (disallowedKeys.includes(event.key)) {
                event.preventDefault();
                return;
            }

            // Allow only numeric values and restrict to 10 digits
            let value = data.value.replace(/\D/g, ''); // Remove non-numeric characters
            if (value.length > 10) {
                value = value.slice(0, 10); // Trim to 10 digits max
            }
            let formattedValue = Number(value).toLocaleString('en-US');

            this.$refs.FieldUpdate.updateProperty("expected_quantity", "value", formattedValue);
        }


    }
}
</script>
<style scoped>
#Location .vue-treeselect {
    padding: 0px;
}

.vue-treeselect .vue-treeselect--disabled .vue-treeselect__control {
    background-color: #e0e0e0 !important;
}

.partition-full .text-white {
    color: #f1f1f1 !important;
}

#Location .vue-treeselect.form-control.is-invalid {
    border-color: #dc3545 !important;
}
</style>
